    #[test]
    fn test_agent_config_payload_with_ldap_config() {
        let ldap = LdapConfigPayload {
            ldap_url: "ldaps://dc.corp.internal:636".to_string(),
            base_dn: "DC=corp,DC=internal".to_string(),
            require_tls: true,
            cache_ttl_secs: 300,
            vpn_subnets: "10.10.0.0/16".to_string(),
        };
        let payload = AgentConfigPayload {
            monitored_paths: vec![r"C:\Data\".to_string()],
            excluded_paths: vec![],
            heartbeat_interval_secs: 60,
            offline_cache_enabled: false,
            ldap_config: Some(ldap),
            disk_allowlist: vec![],
            usb_blocked_failure_mode: "Warning only".to_string(),
            usb_startup_resolution_mode: "VID/PID/serial fallback".to_string(),
            usb_none_serial_policy: "Always Blocked".to_string(),
        };
        let json = serde_json::to_string(&payload).expect("serialize");
        let rt: AgentConfigPayload = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(
            rt.ldap_config.as_ref().map(|c| &c.ldap_url),
            Some(&"ldaps://dc.corp.internal:636".to_string())
        );
    }

    /// Verify that JSON missing the `disk_allowlist` field deserializes to an
    /// empty list (backward compatibility with older server builds).
    #[test]
    fn test_agent_config_payload_disk_allowlist_default_when_missing() {
        // Construct JSON without the disk_allowlist field (simulates an older server).
        let json = r#"{
            "monitored_paths": [],
            "excluded_paths": [],
            "heartbeat_interval_secs": 30,
            "offline_cache_enabled": false,
            "ldap_config": null
        }"#;
        let payload: AgentConfigPayload = serde_json::from_str(json)
            .expect("deserialization must succeed without disk_allowlist");
        // #[serde(default)] must yield an empty Vec when the field is absent.
        assert!(
            payload.disk_allowlist.is_empty(),
            "disk_allowlist must default to empty when absent from server JSON"
        );
    }

    /// Verify that a `disk_allowlist` with two entries survives a serialize/deserialize
    /// roundtrip with all fields intact (PartialEq on DiskIdentity).
    #[test]
    fn test_agent_config_payload_disk_allowlist_roundtrip() {
        use dlp_common::{BusType, DiskIdentity, EncryptionStatus};

        let disks = vec![
            DiskIdentity {
                instance_id: "DISK\\INSTANCE\\0001".to_string(),
                bus_type: BusType::Sata,
                model: "Samsung SSD 870".to_string(),
                drive_letter: Some('C'),
                serial: Some("S123".to_string()),
                size_bytes: Some(500_107_862_016),
                is_boot_disk: true,
                encryption_status: Some(EncryptionStatus::Encrypted),
                encryption_method: None,
                encryption_checked_at: None,
            },
            DiskIdentity {
                instance_id: "DISK\\INSTANCE\\0002".to_string(),
                bus_type: BusType::Nvme,
                model: "WD Black SN850".to_string(),
                drive_letter: Some('D'),
                serial: None,
                size_bytes: None,
                is_boot_disk: false,
                encryption_status: Some(EncryptionStatus::Unencrypted),
                encryption_method: None,
                encryption_checked_at: None,
            },
        ];
        let payload = AgentConfigPayload {
            monitored_paths: vec![],
            excluded_paths: vec![],
            heartbeat_interval_secs: 30,
            offline_cache_enabled: false,
            ldap_config: None,
            disk_allowlist: disks.clone(),
            usb_blocked_failure_mode: "Warning only".to_string(),
            usb_startup_resolution_mode: "VID/PID/serial fallback".to_string(),
            usb_none_serial_policy: "Always Blocked".to_string(),
        };
        let json = serde_json::to_string(&payload).expect("serialize");
        let rt: AgentConfigPayload = serde_json::from_str(&json).expect("deserialize");
        // PartialEq on DiskIdentity covers all fields including encryption_status.
        assert_eq!(
            rt.disk_allowlist, disks,
            "disk_allowlist must survive roundtrip unchanged"
        );
    }

    /// Verify that a JSON payload containing a `disk_allowlist` entry with an
    /// unknown `bus_type` value (from a future server build) deserializes without
    /// panicking, and the unknown variant becomes `BusType::Unknown`.
    ///
    /// This exercises the `#[serde(other)]` marker added to `BusType::Unknown`
    /// in dlp-common for forward compatibility (Pitfall 5 guard).
    #[test]
    fn test_agent_config_payload_disk_allowlist_with_unknown_bus_type() {
        // `"future_bus"` is not a valid BusType variant today; it must map to Unknown.
        let json = r#"{
            "monitored_paths": [],
            "excluded_paths": [],
            "heartbeat_interval_secs": 30,
            "offline_cache_enabled": false,
            "ldap_config": null,
            "disk_allowlist": [
                {
                    "instance_id": "DISK\\INSTANCE\\FUTURE",
                    "bus_type": "future_bus",
                    "model": "FutureDrive X1",
                    "is_boot_disk": false
                }
            ]
        }"#;
        let payload: AgentConfigPayload =
            serde_json::from_str(json).expect("must not fail on unknown bus_type");
        assert_eq!(
            payload.disk_allowlist.len(),
            1,
            "disk_allowlist must contain the entry with the unknown bus_type"
        );
        assert_eq!(
            payload.disk_allowlist[0].bus_type,
            dlp_common::BusType::Unknown,
            "unknown bus_type string must deserialize to BusType::Unknown via #[serde(other)]"
        );
    }

    #[tokio::test]
    async fn test_fetch_agent_config_unreachable() {
        // Use a port on loopback that nothing listens on — fails fast without
        // touching the network or process-wide env vars.
        let sc = ServerClient::from_env_with_config(Some("http://127.0.0.1:19999"))
            .expect("client creation");
        let result = sc.fetch_agent_config().await;
        assert!(result.is_err(), "unreachable server should return error");
    }

    #[tokio::test]
    async fn test_fetch_device_registry_unreachable_server() {
        // Test 5: fetch_device_registry on an unreachable server returns Err (does not panic).
        let client = unreachable_client();
        let result = client.fetch_device_registry().await;
        assert!(result.is_err(), "unreachable server must return Err");
    }

    /// Verify that a mock server response with owner_sid/owner_user fields
    /// deserializes correctly (USB-06, Phase 38.4).
    #[test]
    fn test_fetch_device_registry_with_sid_includes_owner_fields() {
        let json = r#"[{
            "vid": "0951",
            "pid": "1666",
            "serial": "SN001",
            "trust_tier": "blocked",
            "owner_sid": "S-1-5-21-1",
            "owner_user": "alice"
        }]"#;
        let entries: Vec<DeviceRegistryEntry> = serde_json::from_str(json).expect("deserialize");
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].owner_sid, Some("S-1-5-21-1".to_string()));
        assert_eq!(entries[0].owner_user, Some("alice".to_string()));
    }

    /// Verify backward compatibility with older servers that do not emit
    /// owner_sid/owner_user fields (USB-06, Phase 38.4).
    #[test]
    fn test_fetch_device_registry_backward_compat() {
        let json = r#"[{
            "vid": "0951",
            "pid": "1666",
            "serial": "SN001",
            "trust_tier": "full_access"
        }]"#;
        let entries: Vec<DeviceRegistryEntry> = serde_json::from_str(json).expect("deserialize");
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].owner_sid, None);
        assert_eq!(entries[0].owner_user, None);
    }

    #[tokio::test]
    async fn test_fetch_managed_origins_unreachable_server() {
        let client = unreachable_client();
        let result = client.fetch_managed_origins().await;
        assert!(result.is_err(), "unreachable server must return Err");
    }

    // --- Phase 43: USB enforcement config payload tests (USB-07, USB-08, USB-09) ---

    /// Verify that JSON missing the `usb_*` fields deserializes to the
    /// expected default values (backward compatibility with older servers).
    #[test]
    fn test_agent_config_payload_usb_fields_default_when_missing() {
        // Construct JSON without any usb_* fields (simulates an older server).
        let json = r#"{
            "monitored_paths": [],
            "excluded_paths": [],
            "heartbeat_interval_secs": 30,
            "offline_cache_enabled": false,
            "ldap_config": null
        }"#;
        let payload: AgentConfigPayload =
            serde_json::from_str(json).expect("deserialization must succeed without usb fields");
        assert_eq!(
            payload.usb_blocked_failure_mode, "Warning only",
            "usb_blocked_failure_mode must default to 'Warning only'"
        );
        assert_eq!(
            payload.usb_startup_resolution_mode, "VID/PID/serial fallback",
            "usb_startup_resolution_mode must default to 'VID/PID/serial fallback'"
        );
        assert_eq!(
            payload.usb_none_serial_policy, "Always Blocked",
            "usb_none_serial_policy must default to 'Always Blocked'"
        );
    }

    /// Verify that a payload with custom USB values survives a serialize/deserialize
    /// roundtrip with all fields intact.
    #[test]
    fn test_agent_config_payload_usb_fields_roundtrip() {
        let payload = AgentConfigPayload {
            monitored_paths: vec![],
            excluded_paths: vec![],
            heartbeat_interval_secs: 30,
            offline_cache_enabled: false,
            ldap_config: None,
            disk_allowlist: vec![],
            usb_blocked_failure_mode: "Hard error".to_string(),
            usb_startup_resolution_mode: "Volume GUID resolution".to_string(),
            usb_none_serial_policy: "Allow unregistered".to_string(),
        };
        let json = serde_json::to_string(&payload).expect("serialize");
        let rt: AgentConfigPayload = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(rt.usb_blocked_failure_mode, "Hard error");
        assert_eq!(rt.usb_startup_resolution_mode, "Volume GUID resolution");
        assert_eq!(rt.usb_none_serial_policy, "Allow unregistered");
    }
}

