    /// Verify DRAG_DROP is distinct from other Action variants.
    #[test]
    fn test_drag_drop_is_distinct() {
        assert_ne!(Action::DRAG_DROP, Action::PASTE);
        assert_ne!(Action::DRAG_DROP, Action::COPY);
        assert_ne!(Action::DRAG_DROP, Action::READ);
